const previousHeritageStory=heritageStory;
function resolveTale(d){if(d.narrative==='original'||!d.narrative)return storyCatalog.find(s=>s.id===({forest:'falaj-secret',ocean:'turtle-track',space:'missing-moon'}[d.world]||'falaj-secret'));return storyCatalog.find(s=>s.id===({knight:'banner-valley',sailor:'sail-star'}[d.narrative]||d.narrative));}
heritageStory=function(n,d,c){const selected=resolveTale(d);if(!selected)return previousHeritageStory(n,d,c);const a=d.storyLanguage==='ar',l=a?'ar':'en',original=storyCast[selected.lead][l],knownCast=Object.values(storyCast).find(c=>c.ar===n?.trim()||c.en===n?.trim()),name=knownCast?knownCast[l]:(n?.trim()||original);const pages=selected.pages[l].map(text=>text.split(original).join(name));if(d.dedication)pages[0]=d.dedication+'\n\n'+pages[0];return{name,title:selected[l].split(original).join(name),pages,chapters:pages.map((_,i)=>(a?['بداية اللغز','تتبّع الخيوط','اللحظة الحاسمة','انكشاف السرّ']:['The mystery begins','Following the clues','The turning point','The secret revealed'])[Math.min(3,Math.floor(i*4/pages.length))]),historical:false,sources:[],value:a?'حكاية عن الفضول والتعاون وحسن التصرّف':'An adventure in curiosity, teamwork and thoughtful choices',activity:a?'أيّ دليل غيّر مسار الحكاية؟ ماذا كنت ستفعل مكان البطل؟':'Which clue changed the story? What would you have done?',location:d.landmark,storyId:selected.id,artPack:selected.pack,sceneSequence:selected.sequence,cast:{isa:'عيسى',mudrik:'مدرك',somoud:'صمود'}};};
